# Generated by Selenium IDE
import pytest
import time
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC


class TestShippingCompany:
    def setup_method(self, method):
        self.driver = webdriver.Chrome()
        self.driver.maximize_window()
        self.wait = WebDriverWait(self.driver, 10)

    def teardown_method(self, method):
        self.driver.quit()

    def test_shipping_company(self):
        # Navigate to PORTIDE shipping registration portal
        self.driver.get("https://portide.vercel.app/register")

        # Wait for company name field to appear and enter name
        name_field = self.wait.until(
            EC.visibility_of_element_located((By.NAME, "company_name"))
        )
        name_field.send_keys("Maersk Maritime Logistics Ltd")

        # Wait for registration number field and enter legal reg no
        reg_field = self.wait.until(
            EC.visibility_of_element_located((By.NAME, "registration_no"))
        )
        reg_field.send_keys("REG-MRSK-2026-IND")

        # Enter corporate contact email
        email_field = self.wait.until(
            EC.visibility_of_element_located((By.NAME, "email"))
        )
        email_field.send_keys("ops.india@maersk-line.com")

        # Wait for submit button and click it
        submit_btn = self.wait.until(
            EC.element_to_be_clickable((By.CSS_SELECTOR, "button[type='submit']"))
        )
        submit_btn.click()

        # Verify submission receipt and pending review notification
        self.wait.until(EC.presence_of_element_located((By.CLASS_NAME, "status-pending-approval")))
        time.sleep(2)
